class BinaryQueryResultWriterCompactRecordsTest {

	private static final List<String> NAMES = List.of("value");
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@TestFactory
	Stream<DynamicTest> usesPlainStringRecordsByDefault() {
		return BinaryQueryResultWriterEncodingTest.validStrings()
				.map(test -> DynamicTest.dynamicTest(test.description(), () -> {
					Value value = VF.createLiteral(test.value(), CoreDatatype.XSD.STRING);
					byte[] actual = serialize(null, value);
					byte[] expected = document(out -> {
						out.writeByte(BinaryQueryResultConstants.PLAIN_LITERAL_RECORD_MARKER);
						writeString(out, test.value());
					});

					assertArrayEquals(expected, actual);
					assertEquals(List.of(row(value)), parse(actual).getBindingSets());
				}));
	}

	@Test
	void explicitlyRequestedDatatypeRecordsRemainAvailable() throws Exception {
		Value value = VF.createLiteral("hello", CoreDatatype.XSD.STRING);
		byte[] explicit = serialize(false, value);
		byte[] compact = serialize(true, value);

		assertEquals(parse(explicit).getBindingSets(), parse(compact).getBindingSets());
		int namespaceRecordBytes = 1 + 4 + 4
				+ CoreDatatype.XSD.STRING.getIri().getNamespace().getBytes(StandardCharsets.UTF_8).length;
		assertEquals(namespaceRecordBytes + 15, explicit.length - compact.length);
	}

	@Test
	void advertisesThePlainStringSetting() {
		BinaryQueryResultWriter writer = new BinaryQueryResultWriter(new ByteArrayOutputStream());

		assertTrue(writer.getSupportedSettings().contains(BasicWriterSettings.XSD_STRING_TO_PLAIN_LITERAL));
	}

	@Test
	void resetsPlainStringPolicyBetweenDocuments() throws Exception {
		ByteArrayOutputStream output = new ByteArrayOutputStream();
		BinaryQueryResultWriter writer = new BinaryQueryResultWriter(output);
		Value value = VF.createLiteral("hello", CoreDatatype.XSD.STRING);
		writer.getWriterConfig().set(BasicWriterSettings.XSD_STRING_TO_PLAIN_LITERAL, false);
		write(writer, value);
		byte[] explicit = output.toByteArray();
		output.reset();
		writer.getWriterConfig().set(BasicWriterSettings.XSD_STRING_TO_PLAIN_LITERAL, true);
		write(writer, value);

		assertArrayEquals(serialize(false, value), explicit);
		assertArrayEquals(serialize(true, value), output.toByteArray());
	}

	@Test
	void fullIriRecordsAvoidUnprofitableShortNamespaceDeclarations() throws Exception {
		Value first = VF.createIRI("u:", "first");
		Value second = VF.createIRI("urn:", "second");
		byte[] actual = serialize(null, first, second);
		byte[] expected = document(out -> {
			out.writeByte(BinaryQueryResultConstants.URI_RECORD_MARKER);
			writeString(out, first.stringValue());
			out.writeByte(BinaryQueryResultConstants.URI_RECORD_MARKER);
			writeString(out, second.stringValue());
		});

		assertArrayEquals(expected, actual);
		assertEquals(List.of(row(first), row(second)), parse(actual).getBindingSets());
	}

	@Test
	void namespaceSelectionUsesUtf8ByteLength() throws Exception {
		Value shortNamespace = VF.createIRI("é:", "first");
		Value longerNamespace = VF.createIRI("éé:", "second");
		byte[] actual = serialize(null, shortNamespace, longerNamespace);
		byte[] expected = document(out -> {
			out.writeByte(BinaryQueryResultConstants.URI_RECORD_MARKER);
			writeString(out, shortNamespace.stringValue());
			out.writeByte(BinaryQueryResultConstants.NAMESPACE_RECORD_MARKER);
			out.writeInt(0);
			writeString(out, "éé:");
			out.writeByte(BinaryQueryResultConstants.QNAME_RECORD_MARKER);
			out.writeInt(0);
			writeString(out, "second");
		});

		assertArrayEquals(expected, actual);
		assertEquals(List.of(row(shortNamespace), row(longerNamespace)), parse(actual).getBindingSets());
	}

	@Test
	void compactStringsPreserveRepeatNullAndEmptyRowSemantics() throws Exception {
		ByteArrayOutputStream output = new ByteArrayOutputStream();
		BinaryQueryResultWriter writer = new BinaryQueryResultWriter(output);
		BindingSet first = row(VF.createLiteral("hello"));
		BindingSet second = row(VF.createLiteral("hello"));
		BindingSet empty = row((Value) null);
		BindingSet last = row(VF.createLiteral("hello"));
		writer.startQueryResult(NAMES);
		for (BindingSet row : List.of(first, second, empty, last)) {
			writer.handleSolution(row);
		}
		writer.endQueryResult();
		byte[] expected = document(out -> {
			out.writeByte(BinaryQueryResultConstants.PLAIN_LITERAL_RECORD_MARKER);
			writeString(out, "hello");
			out.writeByte(BinaryQueryResultConstants.REPEAT_RECORD_MARKER);
			out.writeByte(BinaryQueryResultConstants.EMPTY_ROW_RECORD_MARKER);
			out.writeByte(BinaryQueryResultConstants.REPEAT_RECORD_MARKER);
		});

		assertArrayEquals(expected, output.toByteArray());
		assertEquals(List.of(first, second, empty, last), parse(output.toByteArray()).getBindingSets());
	}

	private static byte[] serialize(Boolean plainStrings, Value... values) throws Exception {
		ByteArrayOutputStream output = new ByteArrayOutputStream();
		BinaryQueryResultWriter writer = new BinaryQueryResultWriter(output);
		if (plainStrings != null) {
			writer.getWriterConfig().set(BasicWriterSettings.XSD_STRING_TO_PLAIN_LITERAL, plainStrings);
		}
		write(writer, values);
		return output.toByteArray();
	}

	private static void write(BinaryQueryResultWriter writer, Value... values) {
		writer.startQueryResult(NAMES);
		for (Value value : values) {
			writer.handleSolution(row(value));
		}
		writer.endQueryResult();
	}

	private static BindingSet row(Value value) {
		return new ListBindingSet(NAMES, value);
	}

	private static QueryResultCollector parse(byte[] bytes) throws Exception {
		QueryResultCollector collector = new QueryResultCollector();
		BinaryQueryResultParser parser = new BinaryQueryResultParser();
		parser.setQueryResultHandler(collector);
		parser.parseQueryResult(new ByteArrayInputStream(bytes));
		return collector;
	}

	private static byte[] document(RecordWriter records) throws Exception {
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		DataOutputStream out = new DataOutputStream(bytes);
		out.write(BinaryQueryResultConstants.MAGIC_NUMBER);
		out.writeInt(BinaryQueryResultConstants.FORMAT_VERSION);
		out.writeInt(NAMES.size());
		for (String name : NAMES) {
			writeString(out, name);
		}
		records.write(out);
		out.writeByte(BinaryQueryResultConstants.TABLE_END_RECORD_MARKER);
		return bytes.toByteArray();
	}

	private static void writeString(DataOutputStream out, String text) throws Exception {
		byte[] utf8 = text.getBytes(StandardCharsets.UTF_8);
		out.writeInt(utf8.length);
		out.write(utf8);
	}

	@FunctionalInterface
	private interface RecordWriter {
		void write(DataOutputStream out) throws Exception;
	}
}
